fn arccosh(x: Vec<f32>) -> Vec<f32> {
    let n = x.len();
    let mut result = Vec::with_capacity(n);
    for i in 0..n {
        // Compute the inverse hyperbolic cosine of x[i].
        // Using the identity acosh(z) = ln(z + sqrt(z*z - 1))
        let xi = x[i];
        let yi = (xi * xi - 1.0).sqrt().add(xi).ln();
        result.push(yi);
    }
    result
}

